INSERT INTO `whatsapp_templates` (`id`, `event_key`, `event_label`, `template_body`, `is_active`, `send_to_customer`, `send_to_admin`, `available_variables`, `created_at`, `updated_at`) VALUES
(1, 'new_booking', '🆕 New Booking Received', 'Hello *{{customer_name}}*! 🙏\n\nYour booking has been received successfully.\n\n📋 *Booking ID:* {{booking_id}}\n📍 *From:* {{pickup}}\n📍 *To:* {{destination}}\n📅 *Date:* {{travel_date}}\n🚗 *Vehicle:* {{vehicle_category}}\n💰 *Fare:* ₹{{total_amount}}\n\nWe\'ll confirm your booking shortly. For any queries, call us at {{company_phone}}.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"pickup\",\"destination\",\"travel_date\",\"vehicle_category\",\"total_amount\",\"company_phone\"]', '2026-10-23 16:50:39', '2026-10-23 16:50:39'),
(2, 'booking_confirmed', '✅ Booking Confirmed', 'Hello *{{customer_name}}*! ✅\n\nGreat news! Your booking is *CONFIRMED*.\n\n📋 *Booking ID:* {{booking_id}}\n📍 *From:* {{pickup}}\n📍 *To:* {{destination}}\n📅 *Date:* {{travel_date}} at {{travel_time}}\n🚗 *Vehicle:* {{vehicle_category}}\n💰 *Total Fare:* ₹{{total_amount}}\n\nPlease be ready at the pickup point. Call us at {{company_phone}} for any changes.\n\n*Vaishnavi Tours* ✈️', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"pickup\",\"destination\",\"travel_date\",\"travel_time\",\"vehicle_category\",\"total_amount\",\"company_phone\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(3, 'booking_cancelled', '❌ Booking Cancelled', 'Hello *{{customer_name}}*,\n\nYour booking has been *CANCELLED*.\n\n📋 *Booking ID:* {{booking_id}}\n📍 *Route:* {{pickup}} → {{destination}}\n📅 *Was Scheduled:* {{travel_date}}\n\nIf this was a mistake or you need to rebook, please call us at {{company_phone}}.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"pickup\",\"destination\",\"travel_date\",\"company_phone\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(4, 'driver_assigned', '🧑‍✈️ Driver Assigned', 'Hello *{{customer_name}}*! 🧑‍✈️\n\nYour chauffeur has been assigned for Booking *{{booking_id}}*.\n\n👤 *Driver:* {{driver_name}}\n📞 *Driver Contact:* {{driver_phone}}\n🚗 *Vehicle:* {{vehicle_name}} ({{vehicle_number}})\n📅 *Pickup:* {{travel_date}} at {{travel_time}}\n📍 *From:* {{pickup}}\n\nYour driver will contact you before pickup. For help, call {{company_phone}}.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"driver_name\",\"driver_phone\",\"vehicle_name\",\"vehicle_number\",\"travel_date\",\"travel_time\",\"pickup\",\"company_phone\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(5, 'payment_update', '💳 Payment Update', 'Hello *{{customer_name}}*! 💳\n\nPayment update for Booking *{{booking_id}}*:\n\n✅ *Amount Paid:* ₹{{paid_amount}}\n💰 *Total Fare:* ₹{{total_amount}}\n⏳ *Balance:* ₹{{balance_amount}}\n📊 *Payment Status:* {{payment_status}}\n\nThank you for your payment! Call {{company_phone}} for any queries.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"paid_amount\",\"total_amount\",\"balance_amount\",\"payment_status\",\"company_phone\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(6, 'travel_reminder', '⏰ Travel Reminder', 'Hello *{{customer_name}}*! ⏰\n\nFriendly reminder — your trip is *TOMORROW*!\n\n📋 *Booking ID:* {{booking_id}}\n📍 *From:* {{pickup}}\n📍 *To:* {{destination}}\n📅 *Date:* {{travel_date}} at {{travel_time}}\n👤 *Driver:* {{driver_name}}\n📞 *Driver Contact:* {{driver_phone}}\n🚗 *Vehicle:* {{vehicle_name}} ({{vehicle_number}})\n\nPlease be ready 10 mins before pickup. Safe journey! 🙏\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"pickup\",\"destination\",\"travel_date\",\"travel_time\",\"driver_name\",\"driver_phone\",\"vehicle_name\",\"vehicle_number\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(7, 'new_enquiry', '📩 New Enquiry Received', 'Hello *{{name}}*! 📩\n\nThank you for enquiring with Vaishnavi Tours!\n\n📋 *Enquiry ID:* {{enquiry_id}}\n📍 *From:* {{pickup}}\n📍 *To:* {{destination}}\n📅 *Travel Date:* {{travel_date}}\n\nOur team will get back to you shortly with a quote. For urgent queries, call {{company_phone}}.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"name\",\"enquiry_id\",\"pickup\",\"destination\",\"travel_date\",\"company_phone\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(8, 'trip_started', '🚀 Trip Started', 'Hello *{{customer_name}}*! 🚀\n\nYour trip has *STARTED*!\n\n📋 *Booking ID:* {{booking_id}}\n👤 *Driver:* {{driver_name}}\n📞 *Driver Contact:* {{driver_phone}}\n🚗 *Vehicle:* {{vehicle_name}} ({{vehicle_number}})\n📍 *Destination:* {{destination}}\n\nHave a safe and comfortable journey! 🙏\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"driver_name\",\"driver_phone\",\"vehicle_name\",\"vehicle_number\",\"destination\"]', '2026-10-23 16:50:40', '2026-10-23 16:50:40'),
(9, 'trip_completed', '🏁 Trip Completed', 'Hello *{{customer_name}}*! 🏁\n\nYour trip is *COMPLETED*. We hope you had a great experience!\n\n📋 *Booking ID:* {{booking_id}}\n📍 *Route:* {{pickup}} → {{destination}}\n💰 *Total Fare:* ₹{{total_amount}}\n\nWe\'d love your feedback! Visit: {{feedback_url}}\n\nThank you for choosing Vaishnavi Tours! 🙏\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"pickup\",\"destination\",\"total_amount\",\"feedback_url\"]', '2026-10-23 16:50:41', '2026-10-23 16:50:41'),
(10, 'vehicle_assigned', '🚗 Vehicle Assigned', 'Hello *{{customer_name}}*! 🚗\n\nA vehicle has been assigned for your Booking *{{booking_id}}*.\n\n🚗 *Vehicle:* {{vehicle_name}}\n🔢 *Registration:* {{vehicle_number}}\n📅 *Pickup:* {{travel_date}} at {{travel_time}}\n📍 *From:* {{pickup}}\n\nYour driver will be assigned shortly. For queries, call {{company_phone}}.\n\n*Vaishnavi Tours* 🚖', 1, 1, 1, '[\"customer_name\",\"booking_id\",\"vehicle_name\",\"vehicle_number\",\"travel_date\",\"travel_time\",\"pickup\",\"company_phone\"]', '2026-10-23 16:50:41', '2026-10-23 16:50:41');
